{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成订单城市销售额升序汇总",
      "business_question": "按城市汇总已完成订单的销售额总和，并按销售额升序排列。仅看已完成订单，按照城市汇总，按销售额升序排列。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心业务目标（按城市汇总已完成订单销售额并排序），直接支持决策需求。关联所有核心约束：筛选状态、指标求和、分组维度及排序方式。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_sum"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "sales_sum",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
